import React from 'react';
import { placeOrder } from '../api';

export default function Cart({ cart, setCart, onOrderPlaced }) {
  const total = cart.reduce((s,i)=>s + (i.price * i.quantity || 0), 0);

  function remove(productId) {
    setCart(prev => prev.filter(p => p.productId !== productId));
  }

  async function checkout() {
    if (cart.length === 0) { alert('Cart empty'); return; }
    const order = { items: cart.map(i => ({ productId: i.productId, quantity: i.quantity })) };
    try {
      const res = await placeOrder(order);
      if (res && (res.id || res.orderId || res.total != null)) {
        alert('Order placed successfully. Total: ' + (res.total || 'N/A'));
        onOrderPlaced();
      } else {
        alert('Order result: ' + JSON.stringify(res));
      }
    } catch (err) {
      alert('Order failed: ' + err.message);
    }
  }

  return (
    <div>
      <h2>Your Cart</h2>
      {cart.length === 0 ? <div>Empty</div> : (
        <>
          {cart.map(i => (
            <div className="cart-item" key={i.productId}>
              <div>{i.name} x {i.quantity}</div>
              <div>${(i.price * i.quantity).toFixed(2)}</div>
              <button onClick={()=>remove(i.productId)}>Remove</button>
            </div>
          ))}
          <hr />
          <div className="total">Total: ${total.toFixed(2)}</div>
          <button onClick={checkout}>Place order</button>
        </>
      )}
    </div>
  );
}
